mapper.select:
SELECT

FROM `schedule` s
LEFT JOIN `season` se ON s.season_id = se.id AND se.deleted = 0
LEFT JOIN `match` m ON se.match_id = m.id AND m.deleted = 0
LEFT JOIN `stadium` st ON s.stadium_id = st.id AND st.deleted = 0
WHERE s.deleted = 0

    AND s.season_id = #{query.seasonId}


    AND s.stadium_id = #{query.stadiumId}


    AND s.schedule_name LIKE CONCAT('%', #{query.scheduleName}, '%')


    AND s.status = #{query.status}

ORDER BY s.start_time DESC, s.create_time DESC

    LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*)
FROM `schedule` s
WHERE s.deleted = 0

    AND s.season_id = #{query.seasonId}


    AND s.stadium_id = #{query.stadiumId}


    AND s.schedule_name LIKE CONCAT('%', #{query.scheduleName}, '%')


    AND s.status = #{query.status}

